CODE_FILES = ['backend/app/search.py', 'backend/app/domain.py', 'backend/app/github.py',
              'backend/app/semantic.py', 'backend/app/config.py', 'backend/app/storage.py',
              'evaluation/scenario_eval.py', 'evaluation/scenario_report.py']


def now():
    return datetime.now(timezone.utc).isoformat()


def sha_file(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def write(path, value):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + '.tmp')
    temporary.write_text(json.dumps(value, ensure_ascii=False, indent=2), encoding='utf-8')
    os.replace(temporary, path)


def read(path):
    return json.loads(Path(path).read_text(encoding='utf-8'))


def jsonl(path, rows):
    Path(path).write_text(''.join(json.dumps(x, ensure_ascii=False) + '\n' for x in rows), encoding='utf-8')


def rows(path):
    return [json.loads(x) for x in Path(path).read_text(encoding='utf-8').splitlines() if x.strip()]


def code_hashes():
    return {name: sha_file(ROOT / name) for name in CODE_FILES}


def doc_id(repo, number):
    return f'{repo}#{number}'


def corpus(snapshot, scope, labels):
    documents = [x for x in snapshot['issues'] if 'pull_request' not in x
                 and (scope == 'C_raw' or is_bug(x, labels))]
    return {'repository': snapshot['repository'], 'issues': documents, 'scope': scope,
            'version': digest({'scope': scope, 'documents': documents}), 'bug_labels': labels,
            'ids_hash': digest([doc_id(snapshot['repository'], x['number']) for x in documents])}


class BudgetGitHub(GitHubClient):
    def __init__(self, config, directory):
        super().__init__(Settings().github_token)
        self.config, self.directory = config, directory
        self.log = rows(directory / 'http.jsonl') if (directory / 'http.jsonl').exists() else []
        self.pages = []

    def get(self, path, **params):
        if len(self.log) >= self.config['max_http_calls']:
            raise ServiceError('resource_budget', 'HTTP call budget exhausted', 429)
        started = time.perf_counter()
        entry = {'path': path, 'params': params, 'at': now()}
        try:
            response = super().get(path, **params)
            entry.update(status=response.status_code, remaining=response.headers.get('x-ratelimit-remaining'),
                         reset=response.headers.get('x-ratelimit-reset'))
            if path.endswith('/issues') and isinstance(response.json(), list):
                batch = response.json()
                self.pages.append({'path': path, 'params': params, 'items': len(batch),
                                   'non_pr_issues': sum('pull_request' not in x for x in batch),
                                   'next': response.links.get('next', {}).get('url')})
            return response
        except ServiceError as exc:
            entry.update(error=exc.as_dict())
            raise
        finally:
            entry['elapsed_ms'] = (time.perf_counter() - started) * 1000
            self.log.append(entry)
            jsonl(self.directory / 'http.jsonl', self.log)


def prepare(args):
    directory = Path(args.run_dir)
    directory.mkdir(parents=True, exist_ok=True)
    config = read(args.config)
    target = directory / 'manifest.json'
    if target.exists():
        manifest = read(target)
        if digest(config) != manifest['config_hash']:
            raise ValueError('config changed; use a new run directory')
    else:
        git_command = ['git', '-c', f'safe.directory={ROOT.as_posix()}']
        git = lambda *a: subprocess.check_output([*git_command, *a], cwd=ROOT).decode().strip()
        packages = {name: importlib.metadata.version(name) for name in
                    ['numpy', 'torch', 'sentence-transformers', 'transformers', 'rank-bm25', 'httpx', 'pytest']}
        manifest = {'created_at': now(), 'config': config, 'config_hash': digest(config),
                    'code_revision': git('rev-parse', 'HEAD'), 'code_hashes': code_hashes(),
                    'working_diff_hash': hashlib.sha256(subprocess.check_output([*git_command,'diff','--binary'], cwd=ROOT)).hexdigest(),
                    'baseline_uncommitted_paths': git('status','--porcelain').splitlines(),
                    'environment': {'python': platform.python_version(), 'os': platform.system(),
                                    'machine': platform.machine(), 'cpu_logical': os.cpu_count(), 'packages': packages},
                    'snapshots': {}, 'historical_probes': []}
        write(target, manifest)
    client = BudgetGitHub(config, directory)
    try:
        for repo in config['repositories']:
            file = directory / f'{repo.replace("/", "--")}.snapshot.json'
            if file.exists():
                if sha_file(file) != manifest['snapshots'][repo]['file_hash']:
                    raise ValueError('snapshot changed')
                continue
            started = now()
            client.pages = []
            snapshot = client.fetch(repo, config['max_pages'])
            snapshot['bug_labels'] = config['bug_labels']
            write(file, snapshot)
            dates = [x['created_at'] for x in snapshot['issues']]
            meta = {'file': file.name, 'file_hash': sha_file(file), 'started_at': started,
                    'finished_at': now(), 'fetched_count': snapshot['fetched_count'],
                    'issue_count': len(snapshot['issues']), 'bug_count': sum(is_bug(x, config['bug_labels']) for x in snapshot['issues']),
                    'partial': snapshot['partial'], 'pages': client.pages,
                    'oldest_created': min(dates) if dates else None, 'newest_created': max(dates) if dates else None,
                    'empty_body': sum(not x.get('body') for x in snapshot['issues']),
                    'empty_title': sum(not x.get('title') for x in snapshot['issues']),
                    'attachment_links': sum(bool(re.search(r'!\[|user-attachments|githubusercontent', x.get('body') or '')) for x in snapshot['issues'])}
            meta['attachment_note'] = 'Link presence only; inability to understand without attachment is unreviewed.'
            manifest['snapshots'][repo] = meta
            write(target, manifest)
            print(json.dumps({'repository': repo, **{k: meta[k] for k in ['issue_count', 'bug_count', 'partial']} }), flush=True)
        for repo, number in config['historical_probes']:
            if any(x['repository'] == repo and x['number'] == number for x in manifest['historical_probes']):
                continue
            issue = client.get(f'/repos/{repo}/issues/{number}').json()
            write(directory / f'historical-{repo.replace("/", "--")}-{number}.json', issue)
            manifest['historical_probes'].append({'repository': repo, 'number': number, 'title': issue['title'],
                                                   'url': issue['html_url'], 'cohort': 'historical_probe',
                                                   'previously_exposed': True, 'source_hash': digest(issue)})
            write(target, manifest)
    except ServiceError as exc:
        write(directory / 'status.json', {'status': 'BLOCKED_RESOURCE_BUDGET' if exc.code == 'resource_budget' else 'BLOCKED_SOURCE_OR_CONTRACT', 'error': exc.as_dict(), 'at': now()})
        raise
    finally:
        client.close()
    candidates = []
    rng = random.Random(config['seed'])
    for repo in config['repositories']:
        snapshot = read(directory / manifest['snapshots'][repo]['file'])
        documents = list(snapshot['issues'])
        rng.shuffle(documents)
        # Metadata/body screening only. No retrieval is run before queries are frozen.
        candidates.extend({'repository': repo, 'number': x['number'], 'title': x['title'],
                           'body': x.get('body') or '', 'labels': x['labels'], 'url': x['html_url'],
                           'body_hash': digest(issue_text(x)), 'candidate_order': i,
                           'screening_status': 'unreviewed'} for i, x in enumerate(documents[:24]))
    if not (directory / 'candidates.jsonl').exists():
        jsonl(directory / 'candidates.jsonl', candidates)
    if args.cases:
        cases = read(args.cases)
        if (directory / 'cases.jsonl').exists() and sha_file(args.cases) != manifest.get('cases_input_hash'):
            raise ValueError('cases already frozen; use a new run directory')
        if (directory / 'cases.jsonl').exists():
            verify(directory)
            return
        core = [c for c in cases if c['cohort'] == 'core_development']
        seen = set()
        queries = []
        for case in cases:
            if case['family_id'] in seen:
                raise ValueError('duplicate case family')
            seen.add(case['family_id'])
            source = (next((x for x in read(directory / manifest['snapshots'][case['repository']]['file'])['issues']
                            if x['number'] == case['reference_number']), None) if case['cohort'] == 'core_development'
                      else read(directory / f'historical-{case["repository"].replace("/", "--")}-{case["reference_number"]}.json'))
            if not source:
                raise ValueError('core source absent from raw snapshot')
            case['source_hash'] = digest(issue_text(source))
            case['source_doc_ids'] = [doc_id(case['repository'], case['reference_number'])]
            case['source_urls'] = [source['html_url']]
            case['author_exposure'] = 'Agent read current title/body before drafting. Not blind; no retrieved ranks or comments used.'
            case['query_origin'] = 'reconstructed_from_issue'
            for variant, content in case['queries'].items():
                text = query_text(content['problem'], content.get('error', ''), content.get('environment', ''))
                queries.append({'query_id': case['case_id'] + ':' + variant, 'case_id': case['case_id'],
                                'variant': variant, 'language': 'en' if variant == 'C_en_context' else 'ko',
                                **content, 'query_text': text, 'query_sha256': digest(text),
                                'query_review_status': 'unreviewed', 'query_review_evidence': None})
        jsonl(directory / 'cases.jsonl', cases)
        jsonl(directory / 'queries.jsonl', queries)
        manifest.update(cases_hash=digest(cases), cases_input_hash=sha_file(args.cases), queries_hash=digest(queries), cases_frozen_at=now(),
                        core_cases=len(core), total_queries=len(queries), code_hashes=code_hashes())
        write(target, manifest)
        write(directory / 'status.json', {'status':'PREPARED_DRAFT', 'human_review':False})
    else:
        write(directory / 'status.json', {'status':'SOURCES_FROZEN_AWAITING_QUERY_DRAFT', 'candidate_count': len(candidates)})


def verify(directory, require_queries=True):
    manifest = read(directory / 'manifest.json')
    if digest(manifest['config']) != manifest['config_hash']:
        raise ValueError('configuration/model revision hash changed')
    if manifest['code_hashes'] != code_hashes():
        raise ValueError('code hash changed; results cannot be reused')
    for meta in manifest['snapshots'].values():
        if sha_file(directory / meta['file']) != meta['file_hash']:
            raise ValueError('snapshot hash changed')
    if require_queries:
        if digest(rows(directory / 'queries.jsonl')) != manifest['queries_hash'] or digest(rows(directory / 'cases.jsonl')) != manifest['cases_hash']:
            raise ValueError('query or case hash changed')
        for q in rows(directory / 'queries.jsonl'):
            if digest(q['query_text']) != q['query_sha256'] or q['query_text'] != query_text(q['problem'], q.get('error',''), q.get('environment','')):
                raise ValueError('actual search input differs from frozen query')
    return manifest


class PilotSemantic(SemanticSearch):
    def __init__(self, settings, model_directory):
        super().__init__(settings)
        self.model_directory = model_directory
        self.encode_calls = 0
        self.last_query_vectors = None

    def load_model(self):
        if self.model is None:
            import torch
            from sentence_transformers import SentenceTransformer
            torch.set_num_threads(min(4, os.cpu_count() or 1))
            self.model = SentenceTransformer(str(self.model_directory), device='cpu', local_files_only=True, trust_remote_code=False)
            self.revision = self.settings.model_revision

    def encode(self, text, prefix):
        self.encode_calls += 1
        result = super().encode(text, prefix)
        if prefix == 'query: ':
            self.last_query_vectors = result
        return result


class ScenarioEngine:
    def __init__(self, snapshot, semantic):
        self.snapshot, self.semantic = snapshot, semantic
        self.documents = snapshot['issues']
        self.tokens, self.bm25 = build_lexical_index(self.documents)

    def ranking(self, query, method):
        if not self.documents:
            return []
        lexical = lexical_ranking(self.documents, self.tokens, self.bm25, query) if method in {'bm25','hybrid'} else []
        semantic = sorted(self.semantic.scores(self.snapshot, query).items(), key=lambda x: (-x[1],x[0])) if method in {'semantic','hybrid'} else []
        return fuse(lexical, semantic) if method == 'hybrid' else lexical if method == 'bm25' else semantic


def runtime(directory, manifest):
    config = manifest['config']
    service = Settings()
    model = service.data_dir / 'models' / ('models--' + config['model'].replace('/','--')) / 'snapshots' / config['model_revision']
    if not (model / '.issue-finder-complete').exists():
        raise ServiceError('model_unavailable', 'Pinned offline model cache missing; no fake embedding used.', 503)
    settings = replace(service, data_dir=directory / 'index', model_name=config['model'], model_revision=config['model_revision'],
                       device='cpu', chunk_size=config['chunk_size'], chunk_overlap=config['chunk_overlap'])
    return PilotSemantic(settings, model)


def measure_sample(directory, manifest, semantic, snapshots):
    import psutil
    started = time.perf_counter()
    semantic.load_model()
    loading = time.perf_counter() - started
    candidates = [(s['repository'], x) for s in snapshots.values() for x in s['issues']]
    random.Random(manifest['config']['seed']).shuffle(candidates)
    measured = []
    before = psutil.Process().memory_info().rss
    for repo, issue in candidates[:manifest['config']['sample_documents']]:
        text = issue_text(issue)
        tokens = len(semantic.model.tokenizer.encode(text, add_special_tokens=False, verbose=False))
        started = time.perf_counter()
        vectors = semantic.encode(text, 'passage: ')
        measured.append({'doc_id':doc_id(repo,issue['number']), 'tokens':tokens, 'chunks':len(vectors),
                         'seconds':time.perf_counter()-started, 'rss_bytes':psutil.Process().memory_info().rss})
    all_chunks = sum(len(chunk_text(issue_text(x), semantic.model.tokenizer)) for _,x in candidates)
    seconds_per_chunk = sum(x['seconds'] for x in measured) / sum(x['chunks'] for x in measured)
    report = {'model_loading_seconds':loading, 'sample':measured, 'rss_before_bytes':before,
              'rss_after_bytes':psutil.Process().memory_info().rss, 'all_documents':len(candidates), 'all_chunks':all_chunks,
              'estimated_index_seconds':all_chunks*seconds_per_chunk,
              'estimate_note':'20-document sample; linear chunk estimate, not a guarantee. Query cost excluded.'}
    write(directory / 'resource-sample.json', report)
    return report


def make_run(engine, q, case, method, manifest, kind='core'):
    started = time.perf_counter()
    record = {'run_id':f'{q["query_id"]}|{engine.snapshot["scope"]}|{method}|{kind}',
              'query_id':q['query_id'], 'query_sha256':q['query_sha256'], 'case_id':case['case_id'],
              'cohort':case['cohort'], 'repository':case['repository'], 'corpus_scope':engine.snapshot['scope'],
              'corpus_hash':engine.snapshot['version'], 'selected_doc_ids_hash':engine.snapshot['ids_hash'],
              'method':method, 'model_revision':manifest['config']['model_revision'],
              'code_revision':manifest['code_revision'], 'code_hash':digest(manifest['code_hashes']),
              'config_hash':manifest['config_hash'], 'kind':kind, 'error_code':None}
    try:
        ranking = engine.ranking(q['query_text'], method)
        record['status'] = 'empty_corpus' if not engine.documents else 'no_lexical_match' if not ranking and method == 'bm25' else 'ok'
        record['reference_doc_rank'] = next((i for i,(n,_) in enumerate(ranking,1) if n==case.get('reference_number')),None)
        record['ranked_results'] = [{'rank':i,'doc_id':doc_id(case['repository'],n), 'score':s,
                                    'score_type':{'bm25':'bm25','semantic':'cosine_similarity','hybrid':'rrf'}[method]}
                                   for i,(n,s) in enumerate(ranking[:20],1)]
        record['returned_count'] = len(ranking[:5])
        record['elapsed_ms'] = (time.perf_counter()-started)*1000
        if method != 'bm25' and ranking:
            path = engine.semantic.manifest_path(engine.snapshot)
            vectors = dict(engine.semantic.corpora[str(path)])
            diagnostics=[]
            records={x['number']:x for x in engine.documents}
            for n,_ in ranking[:5]:
                matrix=vectors[n] @ engine.semantic.last_query_vectors.T
                di,qi=np.unravel_index(np.argmax(matrix), matrix.shape)
                text=issue_text(records[n])
                chunks=chunk_text(text, engine.semantic.model.tokenizer)
                qchunks=chunk_text(q['query_text'],engine.semantic.model.tokenizer)
                diagnostics.append({'doc_id':doc_id(case['repository'],n),'doc_tokens':len(engine.semantic.model.tokenizer.encode(text,add_special_tokens=False,verbose=False)),
                                    'doc_chunks':len(chunks),'query_chunks':len(qchunks),'document_chunk':int(di),'query_chunk':int(qi),
                                    'document_span':chunks[di][:500],'query_span':qchunks[qi][:500], 'human_span_classification':None})
            record['chunk_diagnostics']=diagnostics
    except Exception as exc:
        record.update(status='execution_error',error_code=getattr(exc,'code',type(exc).__name__),ranked_results=[],returned_count=0,reference_doc_rank=None)
        record['elapsed_ms']=(time.perf_counter()-started)*1000
    return record


def retrieve(args):
    directory=Path(args.run_dir)
    manifest=verify(directory)
    if (directory/'runs.jsonl').exists():
        raise ValueError('runs already exist; frozen results will not be overwritten')
    budget_started=time.perf_counter()
    config=manifest['config']
    snapshots={repo:read(directory/meta['file']) for repo,meta in manifest['snapshots'].items()}
    semantic=runtime(directory,manifest)
    sample=measure_sample(directory,manifest,semantic,snapshots)
    if sample['estimated_index_seconds'] > config['max_compute_seconds']:
        write(directory/'status.json',{'status':'BLOCKED_RESOURCE_BUDGET','reason':'20-document extrapolation exceeds budget'})
        return
    engines={}
    indexing=[]
    for repo,snapshot in snapshots.items():
        raw=corpus(snapshot,'C_raw',config['bug_labels'])
        started=time.perf_counter()
        def progress(p):
            if time.perf_counter()-budget_started > config['max_compute_seconds']:
                write(directory/'status.json',{'status':'BLOCKED_RESOURCE_BUDGET','phase':'indexing','repository':repo})
                raise ServiceError('resource_budget','90-minute compute checkpoint',429)
            if p['embedded_count'] % 50 == 0:
                print(json.dumps({'repository':repo,**p}),flush=True)
        semantic.prepare(raw,raw['issues'],progress)
        indexing.append({'repository':repo,'documents':len(raw['issues']),'seconds':time.perf_counter()-started})
        for scope in config['scopes']:
            selected=corpus(snapshot,scope,config['bug_labels'])
            if scope!='C_raw' and selected['issues']:
                semantic.prepare(selected,selected['issues'],progress)
            engines[(repo,scope)]=ScenarioEngine(selected,semantic)
    write(directory/'indexing.json',indexing)
    cases={x['case_id']:x for x in rows(directory/'cases.jsonl')}
    queries=rows(directory/'queries.jsonl')
    runs=[]
    rng=random.Random(config['seed'])
    for q in queries:
        c=cases[q['case_id']]
        methods=list(config['methods']);rng.shuffle(methods)
        for scope in config['scopes']:
            for method in methods:
                if time.perf_counter()-budget_started > config['max_compute_seconds']:
                    jsonl(directory/'runs.partial.jsonl',runs)
                    write(directory/'status.json',{'status':'BLOCKED_RESOURCE_BUDGET','phase':'retrieval'})
                    return
                run=make_run(engines[(c['repository'],scope)],q,c,method,manifest,
                             'core' if c['cohort']=='core_development' else 'historical')
                runs.append(run)
        print(q['query_id'],len(runs),flush=True)
    jsonl(directory/'runs.jsonl',runs)
    # Representative first case of each repository/stratum, fixed before ranking.
    timing_cases=[]
    for repo in config['repositories']:
        for stratum in ['error_literal','symptom_without_error','condition_sensitive']:
            timing_cases.append(next(c for c in cases.values() if c['repository']==repo and c['stratum']==stratum and c['cohort']=='core_development'))
    timings=[]
    for c in timing_cases:
        q=next(q for q in queries if q['case_id']==c['case_id'] and q['variant']=='B_ko_context')
        for repeat in range(3):
            methods=list(config['methods']);rng.shuffle(methods)
            for method in methods:
                if time.perf_counter()-budget_started > config['max_compute_seconds']:
                    jsonl(directory/'timings.partial.jsonl',timings)
                    write(directory/'status.json',{'status':'BLOCKED_RESOURCE_BUDGET','phase':'warm_timing'})
                    return
                run=make_run(engines[(c['repository'],'C_raw')],q,c,method,manifest,'warm_timing')
                run['repeat']=repeat;timings.append(run)
    jsonl(directory/'timings.jsonl',timings)
    write(directory/'execution.json',{'completed_at':now(),'compute_seconds':time.perf_counter()-budget_started,
          'logical_searches':len(runs),'timing_repeats':len(timings),'encode_calls':semantic.encode_calls,
          'query_count':len(queries),'query_status':'unreviewed','cold_timing_status':'PENDING_SEPARATE_PROCESS_MEASUREMENT',
          'methods_order':'seeded shuffle; warm timing includes fresh query encoding; shared model/index in one process'})
    write(directory/'status.json',{'status':'RANKINGS_READY_UNREVIEWED','human_review':False})


def cold_sample(args):
    """One fresh process, warm OS cache; includes process imports and model/index load."""
    directory=Path(args.run_dir);manifest=verify(directory)
    snapshots=manifest['snapshots'];repo=args.repository
    snapshot=corpus(read(directory/snapshots[repo]['file']),'C_raw',manifest['config']['bug_labels'])
    case=next(c for c in rows(directory/'cases.jsonl') if c['repository']==repo and c['cohort']=='core_development')
    q=next(q for q in rows(directory/'queries.jsonl') if q['case_id']==case['case_id'] and q['variant']=='B_ko_context')
    semantic=runtime(directory,manifest)
    if args.method!='bm25':semantic.load_model()
    engine=ScenarioEngine(snapshot,semantic)
    run=make_run(engine,q,case,args.method,manifest,'cold_timing')
    write(args.output,run)


def cold(args):
    directory=Path(args.run_dir);manifest=verify(directory)
    if (directory/'cold-timings.jsonl').exists():raise ValueError('cold timings already frozen')
    execution=read(directory/'execution.json');used=execution['compute_seconds'];results=[]
    for repo in manifest['config']['repositories']:
        for method in manifest['config']['methods']:
            if used >= manifest['config']['max_compute_seconds']:
                write(directory/'status.json',{'status':'BLOCKED_RESOURCE_BUDGET','phase':'cold_timing'});return
            output=directory/f'cold-{repo.replace("/","--")}-{method}.json'
            started=time.perf_counter()
            try:
                subprocess.run([sys.executable,'-m','evaluation.scenario_eval','cold-sample','--run-dir',str(directory),
                                '--repository',repo,'--method',method,'--output',str(output)],
                               check=True,cwd=ROOT,timeout=manifest['config']['max_compute_seconds']-used,
                               stdout=subprocess.DEVNULL,stderr=subprocess.PIPE)
                run=read(output)
            except (subprocess.SubprocessError,OSError) as exc:
                run={'repository':repo,'method':method,'status':'execution_error','error_code':type(exc).__name__}
            elapsed=time.perf_counter()-started;used+=elapsed
            run['process_wall_ms']=elapsed*1000;run['note']='One sample; fresh process, OS file cache uncontrolled; no corpus re-embedding.'
            results.append(run);print(repo,method,round(elapsed,2),flush=True)
    jsonl(directory/'cold-timings.jsonl',results)
    execution.update(cold_timing_status='COMPLETED',cold_samples=len(results),compute_with_cold_seconds=used)
    write(directory/'execution.json',execution)


def pool_review(directory):
    queries={q['query_id']:q for q in rows(directory/'queries.jsonl')}
    cases={c['case_id']:c for c in rows(directory/'cases.jsonl')}
    pooled={}
    for run in rows(directory/'runs.jsonl'):
        if run['kind']!='core':continue
        key=run['query_id']
        pooled.setdefault(key,set()).update(r['doc_id'] for r in run['ranked_results'][:5])
        pooled[key].update(cases[queries[key]['case_id']]['source_doc_ids'])
    return queries,pooled


def review_article(item_id, query, document):
    url=document['html_url']
    if not re.fullmatch(r'https://github\.com/[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+/issues/\d+',url):
        raise ValueError('untrusted issue link')
    return ('<article><h2>'+html.escape(item_id)+'</h2><h3>질의</h3><pre>'+html.escape(query)+
            '</pre><h3>'+html.escape(document['title'])+'</h3><a rel="noreferrer" href="'+html.escape(url,quote=True)+
            '">GitHub 원문</a><pre>'+html.escape(document.get('body') or '')+'</pre></article>')


def export_review(args):
    directory=Path(args.run_dir);manifest=verify(directory)
    if (directory/'human_reviews.csv').exists():
        raise ValueError('review package already exists; it will not be overwritten')
    queries,pooled=pool_review(directory)
    documents={doc_id(repo,x['number']):x for repo,meta in manifest['snapshots'].items() for x in read(directory/meta['file'])['issues']}
    review=[]
    for qid,ids in pooled.items():
        for did in sorted(ids):
            review.append({'review_item_id':digest([qid,did])[:16],'query_id':qid,'query_sha256':queries[qid]['query_sha256'],
                          'doc_id':did,'document_sha256':digest(issue_text(documents[did])),'grade':None,
                          'condition_relation':'unknown','evidence_scope':'title_body','evidence_quote':'',
                          'evidence_url':documents[did]['html_url'],'reason':'','reviewer_type':'','reviewer_id':'',
                          'reviewed_at':'','review_status':'unreviewed'})
    random.Random(manifest['config']['seed']).shuffle(review)
    jsonl(directory/'review_items.jsonl',review)
    with (directory/'human_reviews.csv').open('w',encoding='utf-8-sig',newline='') as f:
        writer=csv.DictWriter(f,fieldnames=list(review[0]));writer.writeheader();writer.writerows(review)
    with (directory/'query_reviews.csv').open('w',encoding='utf-8-sig',newline='') as f:
        writer=csv.DictWriter(f,fieldnames=['query_id','query_sha256','symptom_faithful','no_solution_leakage','information_change_checked','reviewer_type','reviewer_id','reviewed_at','review_status','reason'])
        writer.writeheader()
        writer.writerows({'query_id':q['query_id'],'query_sha256':q['query_sha256'],'review_status':'unreviewed'} for q in queries.values())
    parts=['<!doctype html><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'"><title>Blind relevance review</title><style>body{font-family:system-ui;max-width:1000px;margin:30px auto;padding:20px}article{border:1px solid #ddd;padding:20px;margin:20px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere}a{color:#624bd4}</style><h1>순위·방법·점수를 가린 사람 검토 자료</h1><p>CSV의 grade(0/1/2), 근거, 실제 reviewer 정보를 채우세요. null은 미판정입니다. 질의 검토는 query_reviews.csv에 별도로 작성하세요. 자동으로 사람 검토 완료로 처리하지 않습니다.</p>']
    for item in review:
        q=queries[item['query_id']];d=documents[item['doc_id']]
        parts.append(review_article(item['review_item_id'],q['query_text'],d))
    (directory/'review.html').write_text('\n'.join(parts),encoding='utf-8')
    write(directory/'review_manifest.json',{'items':len(review),'query_count':len(pooled),'query_reviews_hash':sha_file(directory/'query_reviews.csv'),
          'review_items_hash':sha_file(directory/'review_items.jsonl'),'status':'AWAITING_HUMAN_REVIEW',
          'review_time_seconds':None,'two_case_review_time_seconds':None})
    write(directory/'status.json',{'status':'AWAITING_HUMAN_REVIEW','human_review':False,'review_pairs':len(review)})
    print(json.dumps({'review_pairs':len(review),'queries':len(pooled)}))


def metric_values(result_ids, judgments, status='ok', reference_ids=None):
    if status=='execution_error':return {'hit_at_5':None,'pooled_ndcg_at_5':None,'reason':'execution_error'}
    top=result_ids[:5]
    grades=[judgments.get(d) for d in top]
    hit=1 if 2 in grades else None if None in grades else 0
    reference_ids=set(reference_ids) if reference_ids is not None else set(judgments)
    reference=[g for d,g in judgments.items() if d in reference_ids and g is not None]
    ideal=sum((2**g-1)/math.log2(i+2) for i,g in enumerate(sorted(reference,reverse=True)[:5]))
    ndcg=None if None in grades or ideal==0 else sum((2**g-1)/math.log2(i+2) for i,g in enumerate(grades))/ideal
    return {'hit_at_5':hit,'pooled_ndcg_at_5':ndcg,'reason':'unjudged' if None in grades else 'no_positive_gain_in_judged_reference' if ideal==0 else None}


def validate_human_review(item, expected):
    if item['query_sha256']!=expected['query_sha256'] or item['document_sha256']!=expected['document_sha256']:
        raise ValueError('review hashes differ')
    if item.get('reviewer_type')!='human' or not item.get('reviewer_id') or not item.get('reviewed_at') or item.get('review_status')!='reviewed':
        raise ValueError('human provenance required; machine grades are not accepted')
    datetime.fromisoformat(item['reviewed_at'].replace('Z','+00:00'))
    if item.get('grade') not in ('0','1','2') or not item.get('reason') or not item.get('evidence_quote') or not item.get('evidence_url'):
        raise ValueError('grade and evidence required')
    if item.get('condition_relation') not in {'supports','conflicts','unknown','not_applicable'} or item.get('evidence_scope') not in {'title_body','comment_only','unavailable'}:
        raise ValueError('invalid evidence or condition relation')


def certify_no_answer(document_ids, judgments):
    """Only a completely judged small corpus with no direct match is certified."""
    return bool(document_ids) and all(judgments.get(d) in (0, 1) for d in document_ids)


def score(args):
    directory=Path(args.run_dir);manifest=verify(directory)
    expected={x['review_item_id']:x for x in rows(directory/'review_items.jsonl')}
    queries={q['query_id']:q for q in rows(directory/'queries.jsonl')}
    with Path(args.query_reviews).open(encoding='utf-8-sig',newline='') as f:qreview=list(csv.DictReader(f))
    valid_queries=set()
    for q in qreview:
        if q['review_status']!='reviewed':continue
        if q['query_id'] not in queries or q['query_sha256']!=queries[q['query_id']]['query_sha256']:
            raise ValueError('query review hash mismatch')
        if any(q.get(k)!='yes' for k in ['symptom_faithful','no_solution_leakage','information_change_checked']) or q.get('reviewer_type')!='human' or not q.get('reviewer_id') or not q.get('reviewed_at'):
            raise ValueError('query needs actual human review and information check')
        datetime.fromisoformat(q['reviewed_at'].replace('Z','+00:00'))
        valid_queries.add(q['query_id'])
    with Path(args.reviews).open(encoding='utf-8-sig',newline='') as f:reviews=list(csv.DictReader(f))
    qrels=[];seen=set()
    for item in reviews:
        if item.get('review_status')!='reviewed':continue
        key=item['review_item_id']
        if key not in expected or key in seen:raise ValueError('unknown or duplicate review item')
        seen.add(key);validate_human_review(item,expected[key])
        if item['query_id'] not in valid_queries:raise ValueError('query not reviewed')
        qrels.append({**item,'grade':int(item['grade'])})
    if not qrels:raise ValueError('No actual human reviews supplied')
    jsonl(directory/'qrels.jsonl',qrels)
    raw_ids={doc_id(repo,x['number']) for repo,meta in manifest['snapshots'].items() for x in read(directory/meta['file'])['issues']}
    metrics=[]
    for run in rows(directory/'runs.jsonl'):
        if run['kind']!='core':continue
        judged={x['doc_id']:x['grade'] for x in qrels if x['query_id']==run['query_id'] and x['evidence_scope']=='title_body'}
        values=metric_values([x['doc_id'] for x in run['ranked_results']],judged,run['status'],raw_ids) if run['query_id'] in valid_queries else {'hit_at_5':None,'pooled_ndcg_at_5':None,'reason':'query_unreviewed'}
        metrics.append({k:run[k] for k in ['query_id','case_id','method','corpus_scope','status']}|values)
    with (directory/'metrics.csv').open('w',encoding='utf-8-sig',newline='') as f:
        w=csv.DictWriter(f,fieldnames=list(metrics[0]));w.writeheader();w.writerows(metrics)
    write(directory/'review_receipt.json',{'received_at':now(),'reviews_file_hash':sha_file(args.reviews),'query_reviews_file_hash':sha_file(args.query_reviews),
          'reviewers':len({x['reviewer_id'] for x in qrels}),'single_human_reviewer':len({x['reviewer_id'] for x in qrels})==1,
          'qrels_hash':digest(qrels),'note':'Format/provenance assertions validated; software cannot prove reviewer identity or honesty.'})
    complete=len(valid_queries)>=36 and len(qrels)==len(expected) and all(x['hit_at_5'] is not None or x['status']=='execution_error' for x in metrics)
    write(directory/'status.json',{'status':'PILOT_EVALUATED' if complete else 'PARTIALLY_REVIEWED','human_review':True})


def diagnose(args):
    directory=Path(args.run_dir);verify(directory)
    reviewed=(directory/'qrels.jsonl').exists()
    write(directory/'diagnostics.json',{'E0':'reference coverage/ranks available; relevance UNJUDGED without qrels',
          'E1': 'AWAITING_HUMAN_REVIEW: information-equivalence drafts prepared; not run' if not reviewed else 'PENDING_VALIDATED_VARIANT_REVIEWS',
          'E2':'PENDING_HUMAN_CONDITION_PAIR_VALIDATION', 'E3':'AWAITING_HUMAN_REVIEW: no certified no-answer corpus',
          'E4':'Top-5 max chunk spans recorded; symptom/environment classification unreviewed',
          'E5':'54 warm repetitions run; cold samples tracked separately',
          'external_web_study':'PENDING_MANUAL_STUDY','summary_evaluation':'NOT_APPLICABLE_YET: summary not implemented'})


def main():
    sys.stdout.reconfigure(encoding='utf-8')
    parser=argparse.ArgumentParser(description=__doc__)
    sub=parser.add_subparsers(dest='command',required=True)
    for name in ['prepare','retrieve','cold','cold-sample','export-review','score','diagnose','report']:
        p=sub.add_parser(name);p.add_argument('--run-dir',required=True)
        if name=='prepare':p.add_argument('--config',required=True);p.add_argument('--cases')
        if name=='score':p.add_argument('--reviews',required=True);p.add_argument('--query-reviews',required=True)
        if name=='cold-sample':
            p.add_argument('--repository',required=True);p.add_argument('--method',choices=['bm25','semantic','hybrid'],required=True);p.add_argument('--output',required=True)
    args=parser.parse_args()
    if args.command=='report':
        from evaluation.scenario_report import report
        report(args)
    else:globals()[args.command.replace('-','_')](args)


if __name__=='__main__':main()
